import { choiceFromModel, shortFromModel, matchingFromModel, createGenome, pick, ri, ua, math, gcd } from './shared.js';

const HARD={steps:4,conceptualJumps:2,algebraLoad:2,theoremRecall:2,hiddenRelations:['target_is_derived','intermediate_relation_required'],distractorLogic:['skip_intermediate','wrong_relation','sign_or_base_error','partial_solution'],wordingStyle:'nmt-hard-compact'};
function G({topic,subtopic,family,concept,solutionPath,context='abstract',representation='text',visualTopology=null,combinedTopics=[],parameterPattern='controlled-exact',answerFormat='choice',...extra}){
  return createGenome({topic,subtopic,family,concept,solutionPath,context,representation,visualTopology,combinedTopics,parameterPattern,answerFormat,...HARD,...extra});
}
const exact=(x)=>Math.abs(x-Math.round(x))<1e-9;
const MATCH_CODES=['А','Б','В','Г','Д'];
function shuffled(values){const out=[...values];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]];}return out;}
function matchingPayload(correctValues,distractors=[]){
  const values=[];
  for(const value of [...correctValues,...distractors]){const text=String(value);if(!values.includes(text))values.push(text);}
  let guard=0;while(values.length<5&&guard++<40){const fallback=String(ri(2,30));if(!values.includes(fallback))values.push(fallback);}
  const options=shuffled(values.slice(0,5));
  const pairs={};
  correctValues.forEach((value,i)=>{const index=options.indexOf(String(value));if(index<0)throw new Error('Matching correct option missing');pairs[String(i)]=MATCH_CODES[index];});
  return {options,pairs};
}

// 1. DATA / STATISTICS ---------------------------------------------------------
function chartWeightedDifference(){
  const vals=[ri(18,28),ri(26,38),ri(34,46),ri(22,34)]; const labels=['I','II','III','IV'];
  const max=Math.max(...vals), min=Math.min(...vals); const mean=vals.reduce((a,b)=>a+b,0)/4;
  if(!exact(mean)) return chartWeightedDifference();
  const ans=max-min+mean;
  return choiceFromModel({blueprintId:'data_chart_reading',topic:'probability_stats',variant:'v4-chart-range-plus-mean',question:'На діаграмі подано кількість учасників чотирьох груп. Знайдіть суму розмаху вибірки та її середнього арифметичного.',correct:ua(ans),distractors:[ua(max-min),ua(mean),ua(max+min),ua(vals.reduce((a,b)=>a+b,0))],explanation:`Розмах: ${max}−${min}=${max-min}. Середнє: (${vals.join('+')})/4=${mean}. Сума дорівнює ${ans}.`,genome:G({topic:'probability_stats',subtopic:'Діаграми',family:'data_chart_reading',concept:'range-plus-mean',solutionPath:['read_all_bars','find_extremes','compute_mean','combine_statistics'],representation:'chart',visualTopology:'bar_chart',combinedTopics:['statistics'],visualReasoning:3}),visualSpec:{type:'bar_chart',diagram_type:'bar_chart',data:{values:vals},labels:{categories:labels}},preferredRenderer:'canvas'});
}
function chartPercentChange(){
  const a=pick([20,24,30,32,40]), pct=pick([25,50,75]); const b=a*(1+pct/100); if(!exact(b))return chartPercentChange();
  const c=ri(18,42),d=ri(18,42); const vals=[a,b,c,d];
  return choiceFromModel({blueprintId:'data_chart_reading',topic:'probability_stats',variant:'v4-chart-percent-change',question:'За діаграмою визначте, на скільки відсотків значення у II групі більше, ніж у I групі.',correct:`${pct}%`,distractors:[`${ua(b-a)}%`,`${ua(100*(b-a)/b)}%`,`${ua(100*b/a)}%`,`${ua(pct/2)}%`],explanation:`Приріст дорівнює ${b-a}, базою є значення I групи ${a}. Тому (${b-a})/${a}·100%=${pct}%.`,genome:G({topic:'probability_stats',subtopic:'Діаграми',family:'data_chart_reading',concept:'relative-change-from-chart',solutionPath:['read_two_bars','identify_percent_base','compute_relative_change','convert_to_percent'],representation:'chart',visualTopology:'bar_chart',combinedTopics:['percents'],visualReasoning:3}),visualSpec:{type:'bar_chart',diagram_type:'bar_chart',data:{values:vals},labels:{categories:['I','II','III','IV']}},preferredRenderer:'canvas'});
}
export function generateDataChartV4(){return pick([chartWeightedDifference,chartPercentChange])();}

// 2. PARALLEL LINES / PLANIMETRY ---------------------------------------------
function parallelAngleChain(){const a=pick([48,52,56,64,68]);const b=pick([12,18,22]);const target=180-a-b;return choiceFromModel({blueprintId:'planimetry_angle_parallel',topic:'planimetry',variant:'v4-parallel-angle-chain',question:`Прямі a і b паралельні. Один із внутрішніх односторонніх кутів дорівнює ${a}°. Інший кут поділено променем на два кути, один з яких дорівнює ${b}°. Знайдіть другий із цих двох кутів.`,correct:ua(target),distractors:[ua(180-a),ua(a-b),ua(180-a+b),ua(a+b)],explanation:`Внутрішні односторонні кути в сумі дають 180°. Другий повний кут: ${180-a}°. Після віднімання ${b}° маємо ${target}°.`,genome:G({topic:'planimetry',subtopic:'Кути і паралельні прямі',family:'planimetry_angle_parallel',concept:'same-side-plus-split',solutionPath:['parallel_same_side_sum','derive_full_angle','subtract_subangle','target'],context:'geometry',representation:'diagram',visualTopology:'parallel_lines',visualReasoning:4,theoremRecall:3}),visualSpec:{type:'parallel_lines',diagram_type:'parallel_lines',data:{angle:a},labels:{}}});}
function trapezoidAngle(){const a=pick([58,64,72,76]);const extra=pick([14,18,22]);const d=180-a;const ans=d-extra;return choiceFromModel({blueprintId:'planimetry_angle_parallel',topic:'planimetry',variant:'v4-trapezoid-adjacent-derived',question:`У трапеції ABCD основи AD і BC паралельні. ∠A=${a}°. Діагональ BD ділить кут D на два кути, один з яких дорівнює ${extra}°. Знайдіть другий кут.`,correct:ua(ans),distractors:[ua(d),ua(a-extra),ua(180-a+extra),ua(180-a/2)],explanation:`Кути A і D при бічній стороні доповнюють один одного до 180°, тому ∠D=${d}°. Віднімаємо ${extra}°: ${ans}°.`,genome:G({topic:'planimetry',subtopic:'Трапеція',family:'planimetry_angle_parallel',concept:'trapezoid-adjacent-and-diagonal',solutionPath:['parallel_bases_adjacent_angles','derive_vertex_angle','split_by_diagonal','target'],context:'geometry',representation:'diagram',visualTopology:'trapezoid',visualReasoning:4,theoremRecall:3}),visualSpec:{type:'trapezoid',diagram_type:'trapezoid',data:{top:8,bottom:14,height:6,angle:a},labels:{}}});}
export function generateParallelV4(){return pick([parallelAngleChain,trapezoidAngle])();}

// 3. INEQUALITIES --------------------------------------------------------------
function linearCompound(){const lo=pick([-6,-5,-4,-3]),hi=pick([3,4,5,6]);const k=pick([2,3,4]);const shift=pick([-3,-2,1,2]);const integer=pick([lo+1,lo+2,hi-1]); const left=k*(lo+shift), right=k*(hi+shift);return choiceFromModel({blueprintId:'linear_inequality_pick',topic:'inequalities',variant:'v4-compound-linear-membership',question:`Розв'яжіть подвійну нерівність ${left}<${k}(x+${shift})<${right} і вкажіть число, яке належить множині її розв'язків.`,correct:ua(integer),distractors:[ua(lo-1),ua(lo),ua(hi),ua(hi+1)],explanation:`Ділимо на ${k}: ${lo+shift}<x+${shift}<${hi+shift}. Віднімаємо ${shift}: ${lo}<x<${hi}. Із наведених чисел підходить ${integer}.`,genome:G({topic:'inequalities',subtopic:'Лінійні нерівності',family:'linear_inequality_pick',concept:'compound-transform-membership',solutionPath:['divide_positive_factor','shift_interval','respect_open_bounds','test_options'],algebraLoad:3,combinedTopics:['intervals']})});}
function linearParameterCount(){const a=pick([-4,-3,-2]),b=pick([3,4,5]);const count=b-a-1;const m=pick([2,3]);return choiceFromModel({blueprintId:'linear_inequality_pick',topic:'inequalities',variant:'v4-integer-count-after-transform',question:`Скільки цілих розв'язків має нерівність ${m*a+1}<${m}x+1<${m*b+1}?`,correct:ua(count),distractors:[ua(count+1),ua(count+2),ua(b-a),ua(count-1)],explanation:`Віднімаємо 1 і ділимо на ${m}: ${a}<x<${b}. Цілі числа всередині інтервалу: ${count}.`,genome:G({topic:'inequalities',subtopic:'Лінійні нерівності',family:'linear_inequality_pick',concept:'integer-solutions-count',solutionPath:['isolate_linear_expression','obtain_open_interval','enumerate_integers','count'],algebraLoad:3,combinedTopics:['integers']})});}
export function generateLinearInequalityV4(){return pick([linearCompound,linearParameterCount])();}

// 4. STEREOMETRY CONCEPT -------------------------------------------------------
function prismSpaceDiagonal(){const a=pick([3,4,6]),b=pick([4,6,8]),h=pick([12,8,6]);const d2=a*a+b*b+h*h;const d=Math.sqrt(d2);if(!exact(d))return prismSpaceDiagonal();return choiceFromModel({blueprintId:'solid_geometry_concept',topic:'stereometry',variant:'v4-prism-space-diagonal',question:`Прямокутний паралелепіпед має ребра ${a}, ${b} і ${h}. Знайдіть довжину його просторової діагоналі.`,correct:ua(d),distractors:[ua(Math.sqrt(a*a+b*b)),ua(a+b+h),ua(d2),ua(Math.sqrt(a*b*h))],explanation:`Просторова діагональ d задовольняє d²=${a}²+${b}²+${h}²=${d2}. Отже d=${d}.`,genome:G({topic:'stereometry',subtopic:'Прямокутний паралелепіпед',family:'solid_geometry_concept',concept:'space-diagonal-two-pythagoras',solutionPath:['base_diagonal','combine_with_height','square_root','target'],context:'geometry',representation:'diagram',visualTopology:'solid_3d_rect_prism',visualReasoning:4,theoremRecall:3,combinedTopics:['pythagorean_theorem']}),visualSpec:{type:'rect_prism',diagram_type:'solid',data:{a,b,h,showDiagonal:true},labels:{}},preferredRenderer:'threejs'});}
function cubeSectionArea(){const a=pick([4,6,8,10]);const diag=a*Math.sqrt(2);const area=a*diag;return choiceFromModel({blueprintId:'solid_geometry_concept',topic:'stereometry',variant:'v4-cube-diagonal-section-area',question:`У кубі з ребром ${a} проведено переріз через дві паралельні протилежні ребра так, що одна сторона перерізу є діагоналлю грані. Знайдіть площу цього прямокутного перерізу.`,correct:`${ua(a*a)}√2`,distractors:[ua(a*a),`${ua(2*a*a)}√2`,`${ua(a)}√2`,ua(2*a*a)],explanation:`Сторони перерізу: ребро a=${a} і діагональ грані a√2=${a}√2. Площа дорівнює ${a*a}√2.`,genome:G({topic:'stereometry',subtopic:'Куб',family:'solid_geometry_concept',concept:'diagonal-section-area',solutionPath:['recognize_section_shape','face_diagonal','rectangle_area','target'],context:'geometry',representation:'diagram',visualTopology:'solid_3d_cube',visualReasoning:4,theoremRecall:3}),visualSpec:{type:'cube',diagram_type:'solid',data:{a},labels:{}},preferredRenderer:'threejs'});}
export function generateSolidConceptV4(){return pick([prismSpaceDiagonal,cubeSectionArea])();}

// 5. PROBABILITY ---------------------------------------------------------------
function probabilityWithoutReplacement(){const red=pick([4,5,6]),blue=pick([3,4,5]);const n=red+blue;const num=red*(red-1),den=n*(n-1);const g0=gcd(num,den);return choiceFromModel({blueprintId:'probability_counting_basic',topic:'probability_stats',variant:'v4-two-red-without-replacement',question:`У коробці ${red} червоних і ${blue} синіх куль. Навмання послідовно витягують дві кулі без повернення. Яка ймовірність того, що обидві кулі червоні?`,correct:`${num/g0}/${den/g0}`,distractors:[`${red}/${n}`,`${red*red}/${n*n}`,`${red}/${den}`,`${red*(red-1)}/${n*n}`],explanation:`P=${red}/${n}·${red-1}/${n-1}=${num/g0}/${den/g0}.`,genome:G({topic:'probability_stats',subtopic:'Ймовірність',family:'probability_counting_basic',concept:'without-replacement-dependent-events',solutionPath:['first_probability','update_population','second_probability','multiply_and_reduce'],combinedTopics:['fractions'],algebraLoad:2})});}
function combinatorialAtLeastOne(){const n=pick([5,6,7]);const total=2**n;const unfavorable=1;const num=total-unfavorable,den=total;return choiceFromModel({blueprintId:'probability_counting_basic',topic:'probability_stats',variant:'v4-at-least-one-via-complement',question:`Монету підкидають ${n} разів. Яка ймовірність того, що герб випаде хоча б один раз?`,correct:`${num}/${den}`,distractors:[`1/${den}`,`${n}/${den}`,`${total-n}/${den}`,`1/${n}`],explanation:`Ймовірність жодного герба дорівнює 1/${total}. Тому ймовірність хоча б одного герба: 1−1/${total}=${num}/${den}.`,genome:G({topic:'probability_stats',subtopic:'Ймовірність',family:'probability_counting_basic',concept:'complement-event',solutionPath:['identify_complement','count_all_sequences','count_no-success','subtract_from_one'],combinedTopics:['combinatorics'],conceptualJumps:3})});}
export function generateProbabilityV4(){return pick([probabilityWithoutReplacement,combinatorialAtLeastOne])();}

// 6. VECTORS 3D ---------------------------------------------------------------
function vectorsDotDerived(){const a=[ri(-3,4),ri(-3,4),ri(-3,4)],b=[ri(-3,4),ri(-3,4),ri(-3,4)];if(a.every(x=>x===0)||b.every(x=>x===0))return vectorsDotDerived();const dot=a.reduce((s,x,i)=>s+x*b[i],0);const norm2=a.reduce((s,x)=>s+x*x,0);const ans=dot+norm2;return choiceFromModel({blueprintId:'vectors_3d',topic:'stereometry',variant:'v4-dot-plus-norm-squared',question:`Дано вектори a=(${a.join('; ')}) і b=(${b.join('; ')}). Знайдіть значення a·b+|a|².`,correct:ua(ans),distractors:[ua(dot),ua(norm2),ua(a.reduce((s,x,i)=>s+x+b[i],0)),ua(Math.abs(dot)+norm2)],explanation:`a·b=${dot}, |a|²=${norm2}. Тому шукане значення ${dot}+${norm2}=${ans}.`,genome:G({topic:'stereometry',subtopic:'Вектори у просторі',family:'vectors_3d',concept:'dot-plus-norm',solutionPath:['compute_dot_product','compute_squared_norm','combine_results','target'],representation:'coordinates',combinedTopics:['algebra'],algebraLoad:3})});}
function midpointDistance3d(){const A=[pick([-4,-2,0,2]),pick([-4,-2,0,2]),pick([-4,-2,0,2])];const B=A.map(x=>x+pick([2,4,6]));const M=A.map((x,i)=>(x+B[i])/2);const d2=M.reduce((s,x)=>s+x*x,0);return choiceFromModel({blueprintId:'vectors_3d',topic:'stereometry',variant:'v4-midpoint-distance-squared',question:`Точки A(${A.join('; ')}) і B(${B.join('; ')}) задано в просторі. M — середина відрізка AB. Знайдіть OM², де O — початок координат.`,correct:ua(d2),distractors:[ua(M.reduce((s,x)=>s+Math.abs(x),0)),ua(B.reduce((s,x,i)=>s+(x-A[i])**2,0)),ua(d2/4),ua(Math.sqrt(d2))],explanation:`M=(${M.join('; ')}). Тоді OM²=${M.map(x=>`${x}²`).join('+')}=${d2}.`,genome:G({topic:'stereometry',subtopic:'Координати у просторі',family:'vectors_3d',concept:'midpoint-then-distance',solutionPath:['midpoint_coordinates','distance_formula_squared','sum_coordinates','target'],representation:'coordinates',combinedTopics:['coordinate_geometry'],conceptualJumps:3})});}
export function generateVectorsV4(){return pick([vectorsDotDerived,midpointDistance3d])();}

// 7. ALGEBRA SIMPLIFY ----------------------------------------------------------
function rationalIdentityValue(){const x=pick([3,4,5,6]),a=pick([1,2]);const val=(x*x-a*a)/(x-a)-(x+a)/2;const ans=(x+a)/2;return choiceFromModel({blueprintId:'algebra_simplify',topic:'numbers',variant:'v4-factor-cancel-combine',question:`Обчисліть значення виразу ${math(`\\frac{x^2-${a*a}}{x-${a}}-\\frac{x+${a}}{2}`)} при x=${x}.`,correct:ua(ans),distractors:[ua(x+a),ua(x-a),ua((x-a)/2),ua(val+a)],explanation:`x²−${a*a}=(x−${a})(x+${a}), тому перший дріб дорівнює x+${a}. Після віднімання половини отримуємо (x+${a})/2=${ua(ans)}.`,genome:G({topic:'numbers',subtopic:'Вирази',family:'algebra_simplify',concept:'factor-cancel-then-combine',solutionPath:['difference_of_squares','cancel_factor','combine_like_fraction','substitute_value'],algebraLoad:4,combinedTopics:['fractions']})});}
function nestedFraction(){const a=pick([2,3,4]),b=pick([5,6,7]);const x=pick([2,3]);const ans=(a*x+b)/(x);return choiceFromModel({blueprintId:'algebra_simplify',topic:'numbers',variant:'v4-nested-fraction-value',question:`Знайдіть значення ${math(`\\frac{${a}+\\frac{${b}}{x}}{1}`)} при x=${x}.`,correct:ua(ans),distractors:[ua((a+b)/x),ua(a+b*x),ua(a*x+b),ua(a+b/x/x)],explanation:`${a}+${b}/${x}=(${a*x}+${b})/${x}=${ua(ans)}.`,genome:G({topic:'numbers',subtopic:'Вирази',family:'algebra_simplify',concept:'nested-fraction-rewrite',solutionPath:['common_denominator','combine_numerator','substitute','simplify'],algebraLoad:3,combinedTopics:['fractions']})});}
export function generateAlgebraSimplifyV4(){return pick([rationalIdentityValue,nestedFraction])();}

// 8. GEOMETRY STATEMENTS -------------------------------------------------------
function statementsQuadrilateral(){const correct='У ромбі діагоналі перпендикулярні й ділять кути навпіл.';const opts=['У будь-якому паралелограмі діагоналі рівні.','У будь-якій трапеції діагоналі перпендикулярні.','У прямокутнику діагоналі завжди перпендикулярні.','У довільному чотирикутнику сума двох протилежних кутів дорівнює 180°.'];return choiceFromModel({blueprintId:'geometry_statements',topic:'planimetry',variant:'v4-quadrilateral-property-logic',question:'Оберіть твердження, яке є правильним для кожної фігури зазначеного типу.',correct,distractors:opts,explanation:'У ромбі діагоналі взаємно перпендикулярні та є бісектрисами його кутів. Інші твердження не є загальними властивостями названих фігур.',genome:G({topic:'planimetry',subtopic:'Властивості фігур',family:'geometry_statements',concept:'necessary-property-discrimination',solutionPath:['parse_universal_claims','recall_quadrilateral_properties','find_counterexamples','select_invariant'],theoremRecall:4,conceptualJumps:3})});}
function statementsCircle(){const correct='Якщо вписаний кут спирається на діаметр, то він прямий.';return choiceFromModel({blueprintId:'geometry_statements',topic:'planimetry',variant:'v4-circle-property-logic',question:'Яке з наведених тверджень завжди правильне?',correct,distractors:['Будь-яка хорда кола є його діаметром.','Центральний кут дорівнює половині вписаного кута, що спирається на ту саму дугу.','Дві довільні хорди одного кола мають однакову довжину.','Радіус, проведений до довільної точки хорди, перпендикулярний до неї.'],explanation:'За теоремою Фалеса вписаний кут, що спирається на діаметр, дорівнює 90°.',genome:G({topic:'planimetry',subtopic:'Властивості кола',family:'geometry_statements',concept:'circle-theorem-discrimination',solutionPath:['evaluate_each_claim','recall_circle_theorems','reject_nonuniversal','select_theorem'],theoremRecall:4,conceptualJumps:3})});}
export function generateGeometryStatementsV4(){return pick([statementsQuadrilateral,statementsCircle])();}

// 9. LOG / EXP -----------------------------------------------------------------
function logEquationShift(){const base=pick([2,3,5]),r=pick([2,3,4]);const shift=pick([1,2,3]);const x=base**r-shift;return choiceFromModel({blueprintId:'log_exp_equation_interval',topic:'logarithms',variant:'v4-log-shift-equation',question:`Розв'яжіть рівняння ${math(`\\log_{${base}}(x+${shift})=${r}`)} і вкажіть проміжок, якому належить його корінь.`,correct:`(${x-1}; ${x+1})`,distractors:[`(${x+1}; ${x+3})`,`(${x-3}; ${x-1})`,`(0; ${r+shift})`,`(${base**r}; ${base**r+2})`],explanation:`x+${shift}=${base}^${r}=${base**r}, тому x=${x}. Він належить проміжку (${x-1}; ${x+1}).`,genome:G({topic:'logarithms',subtopic:'Рівняння',family:'log_exp_equation_interval',concept:'log-equation-interval-membership',solutionPath:['domain_check','convert_log_to_exponential','solve_linear_shift','locate_root_interval'],algebraLoad:3,theoremRecall:3})});}
function exponentialSubstitution(){const base=pick([2,3]);const t=pick([2,3,4]);const x=Math.round(Math.log(t)/Math.log(base)); if(base**x!==t)return exponentialSubstitution();const ans=x+1;return choiceFromModel({blueprintId:'log_exp_equation_interval',topic:'logarithms',variant:'v4-exponential-common-base',question:`Знайдіть x+1, якщо ${math(`${base}^{2x}-${t+1}\\cdot ${base}^x+${t}=0`)}. Відомо, що ${base}^x>1.`,correct:ua(ans),distractors:[ua(x),ua(t),ua(t+1),ua(2*x)],explanation:`Позначимо y=${base}^x. Маємо y²−${t+1}y+${t}=0, тобто y=1 або y=${t}. За умовою y>1, тому ${base}^x=${t}, x=${x}, отже x+1=${ans}.`,genome:G({topic:'logarithms',subtopic:'Показникові рівняння',family:'log_exp_equation_interval',concept:'exponential-quadratic-substitution',solutionPath:['substitute_exponential','solve_quadratic_in_substitution','use_condition_to_select_root','recover_x'],algebraLoad:4,combinedTopics:['quadratic_equations'],conceptualJumps:3})});}
