function shortParameterRoots(){const a=pick([2,3,4,5]);const b=pick([1,2,3]);const ans=a*a;return shortFromModel({blueprintId:'short_parameter_roots',topic:'equations',variant:'v4-parameter-double-root-short',question:`За якого найменшого невід'ємного значення m рівняння ${math(`x^2-2${a}x+m=0`)} має рівно один дійсний корінь?`,correctValue:ans,explanation:`Рівно один корінь: D=0. D=(${2*a})²−4m=0, звідси m=${a*a}.`,genome:G({topic:'equations',subtopic:'Параметри',family:'short_parameter_roots',concept:'parameter-for-double-root',solutionPath:['translate_root_count_to_discriminant','set_discriminant_zero','solve_parameter','verify_nonnegative'],answerFormat:'short',combinedTopics:['quadratic_equations'],algebraLoad:4,conceptualJumps:3})});}
