// 20. SYSTEMS ------------------------------------------------------------------
function systemDerived(){const x=pick([2,3,4,5]),y=pick([1,2,3]);const a=pick([2,3]),b=pick([2,3]);const s1=a*x+y,s2=x-b*y;const target=x*y+x;return choiceFromModel({blueprintId:'systems_linear',topic:'systems',variant:'v4-system-derived-expression',question:`Розв'яжіть систему ${math(`\\begin{cases}${a}x+y=${s1}\\\\x-${b}y=${s2}\\end{cases}`)} і знайдіть x(y+1).`,correct:ua(target),distractors:[ua(x*y),ua(x+y),ua(target+y),ua(s1+s2)],explanation:`Із системи отримуємо x=${x}, y=${y}. Тоді x(y+1)=${x}·${y+1}=${target}.`,genome:G({topic:'systems',subtopic:'Системи',family:'systems_linear',concept:'solve-system-then-derived-target',solutionPath:['eliminate_variable','solve_first_variable','back_substitute','evaluate_derived_expression'],algebraLoad:4,conceptualJumps:2})});}
function systemParameter(){const x=pick([2,3,4]),y=pick([1,2,3]);const s=x+y,d=x-y;const ans=x*x-y*y;return choiceFromModel({blueprintId:'systems_linear',topic:'systems',variant:'v4-sum-difference-product-identity',question:`Відомо, що x+y=${s}, x−y=${d}. Знайдіть x²−y².`,correct:ua(ans),distractors:[ua(s*s-d*d),ua(s+d),ua(x*x+y*y),ua(s*d+1)],explanation:`x²−y²=(x+y)(x−y)=${s}·${d}=${ans}.`,genome:G({topic:'systems',subtopic:'Системи',family:'systems_linear',concept:'system-to-identity',solutionPath:['recognize_sum_difference','use_difference_of_squares','multiply_given_relations','target'],combinedTopics:['identities'],conceptualJumps:3})});}
