function apNthFromSum(){const a1=pick([2,3,5]),d=pick([2,3,4]),n=pick([8,10,12]);const an=a1+(n-1)*d;const sum=n*(a1+an)/2;const target=an-a1;return choiceFromModel({blueprintId:'progression_ap',topic:'progressions',variant:'v4-ap-sum-and-gap',question:`В арифметичній прогресії a₁=${a1}, d=${d}. Знайдіть різницю a${n}−a₁.`,correct:ua(target),distractors:[ua(an),ua(sum),ua(n*d),ua((n-1)+d)],explanation:`a${n}=a₁+(${n}−1)d, тому a${n}−a₁=(${n-1})·${d}=${target}.`,genome:G({topic:'progressions',subtopic:'Арифметична прогресія',family:'progression_ap',concept:'nth-term-gap',solutionPath:['recall_nth_term','subtract_first_term','simplify_difference','target'],algebraLoad:3,theoremRecall:3})});}
function apRecoverDifference(){const a1=pick([2,4,6]),n=pick([6,8,10]),d=pick([2,3,4]);const an=a1+(n-1)*d;const sum=n*(a1+an)/2;return choiceFromModel({blueprintId:'progression_ap',topic:'progressions',variant:'v4-ap-recover-d-from-sum',question:`Сума перших ${n} членів арифметичної прогресії дорівнює ${sum}, а перший член — ${a1}. Знайдіть різницю прогресії.`,correct:ua(d),distractors:[ua(an),ua(sum/n),ua((an-a1)/n),ua(d+1)],explanation:`Sₙ=n(2a₁+(n−1)d)/2. Підставляємо: ${sum}=${n}(2·${a1}+${n-1}d)/2. Звідси d=${d}.`,genome:G({topic:'progressions',subtopic:'Арифметична прогресія',family:'progression_ap',concept:'recover-difference-from-sum',solutionPath:['write_sum_formula','substitute_knowns','solve_linear_for_d','verify'],algebraLoad:4,theoremRecall:3,conceptualJumps:2})});}
export function generateProgressionV4(){return pick([apNthFromSum,apRecoverDifference])();}

// 22. POWERS / ROOTS -----------------------------------------------------------
function exponentChain(){const a=pick([2,3,5]),m=pick([2,3,4]),n=pick([1,2]);const ans=a**(m-n);return choiceFromModel({blueprintId:'powers_roots_transform',topic:'powers_roots',variant:'v4-power-ratio-chain',question:`Обчисліть ${math(`\\frac{${a}^{${m+2}}\\cdot ${a}^{${n}}}{${a}^{${n+2}}\\cdot ${a}^{${n}}}`)}.` ,correct:ua(ans),distractors:[ua(a**(m+n)),ua(a**m),ua(a**(m-n+2)),ua(m-n)],explanation:`Показники в чисельнику й знаменнику віднімаються. Після скорочення отримуємо ${a}^${m-n}=${ans}.`,genome:G({topic:'powers_roots',subtopic:'Степені та корені',family:'powers_roots_transform',concept:'exponent-balance',solutionPath:['combine_numerator_exponents','combine_denominator_exponents','subtract_exponents','evaluate'],algebraLoad:4,theoremRecall:3})});}
function radicalRationalize(){const a=pick([2,3,5]);const ans=a+1;return choiceFromModel({blueprintId:'powers_roots_transform',topic:'powers_roots',variant:'v4-conjugate-rationalization',question:`Спростіть ${math(`(\\sqrt{${a}}+1)(\\sqrt{${a}}-1)+2`)}.` ,correct:ua(ans),distractors:[ua(a-1),ua(a+2),`${a}√${a}`,ua(2*a)],explanation:`Добуток спряжених: (√${a}+1)(√${a}−1)=${a}−1. Додаємо 2: ${a+1}.`,genome:G({topic:'powers_roots',subtopic:'Степені та корені',family:'powers_roots_transform',concept:'conjugate-product',solutionPath:['recognize_conjugates','difference_of_squares','eliminate_radical','combine_constant'],algebraLoad:3,theoremRecall:3})});}
export function generatePowersV4(){return pick([exponentChain,radicalRationalize])();}

