function similarAreaRatio(){const k=pick([2,3,4]),small=pick([12,18,20]);const big=small*k*k;const ans=big-small;return choiceFromModel({blueprintId:'similar_triangles_ratio',topic:'planimetry',variant:'v4-similar-area-difference',question:`Коефіцієнт подібності двох трикутників (від меншого до більшого) дорівнює ${k}. Площа меншого трикутника — ${small}. На скільки площа більшого трикутника більша?`,correct:ua(ans),distractors:[ua(small*k),ua(big),ua(small*(k-1)),ua(k*k)],explanation:`Площі подібних фігур відносяться як k²=${k*k}. Площа більшого: ${small}·${k*k}=${big}. Різниця: ${ans}.`,genome:G({topic:'planimetry',subtopic:'Подібність',family:'similar_triangles_ratio',concept:'area-scale-difference',solutionPath:['square_similarity_coefficient','compute_large_area','subtract_small_area','target'],context:'geometry',representation:'diagram',visualTopology:'similar_triangles',visualReasoning:3,theoremRecall:4}),visualSpec:{type:'similar_triangles',diagram_type:'similar_triangles',data:{bigBase:9,smallBase:9/k},labels:{}}});}
function similarPerimeter(){const k=pick([1.5,2,2.5]),pSmall=pick([20,24,30,32]);const pBig=pSmall*k;if(!exact(pBig))return similarPerimeter();const sideBig=pick([9,12,15]);const sideSmall=sideBig/k;if(!exact(sideSmall))return similarPerimeter();const ans=pBig+sideSmall;return choiceFromModel({blueprintId:'similar_triangles_ratio',topic:'planimetry',variant:'v4-similar-perimeter-and-side',question:`Два трикутники подібні з коефіцієнтом ${ua(k)} (від меншого до більшого). Периметр меншого — ${pSmall}, а одна сторона більшого — ${sideBig}. Знайдіть суму периметра більшого та відповідної сторони меншого.`,correct:ua(ans),distractors:[ua(pSmall+sideBig),ua(pBig+sideBig),ua(pSmall*k+sideBig*k),ua(pSmall+sideSmall)],explanation:`Периметр більшого: ${pSmall}·${ua(k)}=${pBig}. Відповідна менша сторона: ${sideBig}/${ua(k)}=${sideSmall}. Сума: ${ans}.`,genome:G({topic:'planimetry',subtopic:'Подібність',family:'similar_triangles_ratio',concept:'linear-scale-perimeter-and-side',solutionPath:['scale_perimeter','inverse_scale_side','combine_results','target'],context:'geometry',representation:'diagram',visualTopology:'similar_triangles',visualReasoning:3,theoremRecall:3}),visualSpec:{type:'similar_triangles',diagram_type:'similar_triangles',data:{bigBase:sideBig,smallBase:sideSmall},labels:{}}});}
