function quadraticIntervalCount(){const r1=pick([-5,-4,-3,-2]),r2=pick([3,4,5,6]);const count=r2-r1-1;return choiceFromModel({blueprintId:'quadratic_inequality_interval',topic:'inequalities',variant:'v4-quadratic-open-interval-integer-count',question:`Скільки цілих розв'язків має нерівність ${math(`(x-${r1})(x-${r2})<0`)}?`,correct:ua(count),distractors:[ua(count+1),ua(count+2),ua(r2-r1),ua(count-1)],explanation:`Добуток від'ємний між коренями: ${r1}<x<${r2}. Кількість цілих чисел усередині — ${count}.`,genome:G({topic:'inequalities',subtopic:'Квадратні нерівності',family:'quadratic_inequality_interval',concept:'interval-method-integer-count',solutionPath:['find_zeros','determine_sign_interval','apply_strict_bounds','count_integers'],algebraLoad:3,theoremRecall:3,combinedTopics:['integers']})});}
function quadraticShift(){const h=pick([-3,-2,1,2]),r=pick([2,3,4]);const lo=h-r,hi=h+r;const ans=hi-lo;return choiceFromModel({blueprintId:'quadratic_inequality_interval',topic:'inequalities',variant:'v4-square-inequality-span',question:`Розв'яжіть нерівність ${math(`(x-${h})^2<${r*r}`)}. Чому дорівнює довжина проміжку розв'язків?`,correct:ua(ans),distractors:[ua(r),ua(r*r),ua(hi),ua(Math.abs(lo))],explanation:`|x−${h}|<${r}, тому ${lo}<x<${hi}. Довжина проміжку: ${hi}−(${lo})=${ans}.`,genome:G({topic:'inequalities',subtopic:'Квадратні нерівності',family:'quadratic_inequality_interval',concept:'square-inequality-interval-length',solutionPath:['convert_square_to_absolute','form_double_inequality','derive_endpoints','compute_interval_length'],combinedTopics:['absolute_value'],conceptualJumps:3})});}
