// 25. WORK RATE ----------------------------------------------------------------
function workTogetherThenOne(){const t1=pick([6,8,12]),t2=pick([12,24,18]);const totalRate=1/t1+1/t2;const together=pick([2,3]);const done=together*totalRate;if(done>=1)return workTogetherThenOne();const remain=1-done;const time2=remain*t2;const total=together+time2;if(!exact(total))return workTogetherThenOne();return choiceFromModel({blueprintId:'word_work_rate',topic:'word_problems',variant:'v4-work-together-then-one',question:`Перший працівник виконує роботу сам за ${t1} год, другий — за ${t2} год. Вони працювали разом ${together} год, після чого перший пішов. Скільки годин від початку роботи потрібно, щоб роботу було завершено?`,correct:ua(total),distractors:[ua(1/totalRate),ua(time2),ua(together+t2*(1-together/t1)),ua(t1+t2)],explanation:`За ${together} год разом виконано ${ua(done*100)}% роботи. Решту ${ua(remain*100)}% другий виконає за ${time2} год. Загалом ${total} год.`,genome:G({topic:'word_problems',subtopic:'Спільна робота',family:'word_work_rate',concept:'joint-then-single-rate',solutionPath:['convert_times_to_rates','compute_joint_fraction','find_remaining_fraction','single_worker_time'],context:'applied',combinedTopics:['fractions','rates'],algebraLoad:3,conceptualJumps:3})});}
function workEfficiencyChange(){const t=pick([10,12,15,20]),increase=pick([20,25,50]);const newTime=t/(1+increase/100);if(!exact(newTime))return workEfficiencyChange();const saved=t-newTime;return choiceFromModel({blueprintId:'word_work_rate',topic:'word_problems',variant:'v4-productivity-increase-time-saved',question:`Працівник виконував роботу за ${t} год. Після підвищення продуктивності на ${increase}% обсяг роботи залишився тим самим. На скільки годин зменшився час виконання роботи?`,correct:ua(saved),distractors:[ua(t*increase/100),ua(newTime),ua(t/(increase/100)),ua(increase/10)],explanation:`Час обернено пропорційний продуктивності: новий час ${t}/${1+increase/100}=${newTime}. Економія: ${saved} год.`,genome:G({topic:'word_problems',subtopic:'Спільна робота',family:'word_work_rate',concept:'inverse-rate-productivity-change',solutionPath:['translate_percent_productivity','use_inverse_proportionality','compute_new_time','subtract_times'],context:'applied',combinedTopics:['percents','rates'],conceptualJumps:3})});}
export function generateWorkV4(){return pick([workTogetherThenOne,workEfficiencyChange])();}

// 26. MOTION -------------------------------------------------------------------
function riverRoundTrip(){const v=pick([12,15,18]),u=pick([2,3]);const s=pick([30,36,45]);const t=s/(v+u)+s/(v-u);if(!exact(t*10)/10)return riverRoundTrip();return choiceFromModel({blueprintId:'word_motion',topic:'word_problems',variant:'v4-river-roundtrip',question:`Власна швидкість човна ${v} км/год, швидкість течії ${u} км/год. Човен пройшов ${s} км за течією і стільки ж проти течії. Скільки годин тривав увесь шлях?`,correct:ua(t),distractors:[ua(2*s/v),ua(s/(v+u)),ua(s/(v-u)),ua(2*s/(v+u))],explanation:`Час за течією: ${s}/(${v}+${u}); проти течії: ${s}/(${v}−${u}). Сума дорівнює ${ua(t)} год.`,genome:G({topic:'word_problems',subtopic:'Рух',family:'word_motion',concept:'river-roundtrip',solutionPath:['derive_downstream_speed','derive_upstream_speed','compute_two_times','sum_times'],context:'applied',combinedTopics:['rates','fractions'],algebraLoad:3,conceptualJumps:2})});}
function pursuit(){const slow=pick([50,60,70]),fast=slow+pick([20,30,40]);const lead=pick([40,60,80,90]);const t=lead/(fast-slow);if(!exact(t*10)/10)return pursuit();return choiceFromModel({blueprintId:'word_motion',topic:'word_problems',variant:'v4-pursuit-relative-speed',question:`Автомобіль A рухається зі швидкістю ${slow} км/год і має фору ${lead} км. Автомобіль B рухається в тому самому напрямку зі швидкістю ${fast} км/год. Через скільки годин B наздожене A?`,correct:ua(t),distractors:[ua(lead/fast),ua(lead/slow),ua(lead/(fast+slow)),ua((fast-slow)/lead)],explanation:`Відносна швидкість зближення: ${fast}−${slow}=${fast-slow} км/год. Час: ${lead}/${fast-slow}=${ua(t)} год.`,genome:G({topic:'word_problems',subtopic:'Рух',family:'word_motion',concept:'pursuit-relative-speed',solutionPath:['identify_same-direction_motion','compute_relative_speed','divide_lead_by_relative_speed','target'],context:'applied',combinedTopics:['rates'],conceptualJumps:3})});}
export function generateMotionV4(){return pick([riverRoundTrip,pursuit])();}
